	/*
     * @param	event CreateConsentEvent
     */
    @EventHandler( payloadType=CreateConsentEvent.class )
    public void handle( CreateConsentEvent event) {
	    LOGGER.info("handling CreateConsentEvent - " + event );
	    Consent entity = new Consent();
            entity.setConsentId( event.getConsentId() );
            entity.setGrantedAt( event.getGrantedAt() );
            entity.setExpiresAt( event.getExpiresAt() );
            entity.setScope( event.getScope() );
            entity.setConsentType( event.getConsentType() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllConsent( entity );
    }

    /*
     * @param	event UpdateConsentEvent
     */
    @EventHandler( payloadType=UpdateConsentEvent.class )
    public void handle( UpdateConsentEvent event) {
    	LOGGER.info("handling UpdateConsentEvent - " + event );
    	
	    Consent entity = new Consent();
            entity.setConsentId( event.getConsentId() );
            entity.setGrantedAt( event.getGrantedAt() );
            entity.setExpiresAt( event.getExpiresAt() );
            entity.setScope( event.getScope() );
            entity.setCustomer( event.getCustomer() );
            entity.setApiClient( event.getApiClient() );
            entity.setConsentType( event.getConsentType() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindConsent( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllConsent( entity );        
    }
    
