    /**
     * Method to retrieve the Consent via an ConsentPrimaryKey.
     * @param 	id Long
     * @return 	Consent
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Consent handle( FindConsentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getConsentId() );
    }
    
    /**
     * Method to retrieve a collection of all Consents
     *
     * @param	query	FindAllConsentQuery 
     * @return 	List<Consent> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Consent> handle( FindAllConsentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindConsent,
 * but only if the id matches
 *
 * @param		entity	Consent
 */
	protected void emitFindConsent( Consent entity ) {
		LOGGER.info("handling emitFindConsent" );
		
	    queryUpdateEmitter.emit(FindConsentQuery.class,
	                            query -> query.getFilter().getConsentId().equals(entity.getConsentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllConsent
	 * 
	 * @param		entity	Consent
	 */
	protected void emitFindAllConsent( Consent entity ) {
		LOGGER.info("handling emitFindAllConsent" );
		
	    queryUpdateEmitter.emit(FindAllConsentQuery.class,
	                            query -> true,
	                            entity);
	}

